<?php
declare(strict_types=1);
return static function(PDO$pdo):void{
 $columns=$pdo->query('SHOW COLUMNS FROM committees')->fetchAll(PDO::FETCH_COLUMN);if(!in_array('department_head_staff_id',$columns,true))$pdo->exec('ALTER TABLE committees ADD COLUMN department_head_staff_id INT NULL AFTER secretary_staff_id,ADD COLUMN quorum_percent TINYINT UNSIGNED NOT NULL DEFAULT 50 AFTER department_head_staff_id,ADD CONSTRAINT fk_committee_department_head FOREIGN KEY(department_head_staff_id) REFERENCES program_staff(id) ON DELETE SET NULL');
 $meetingColumns=$pdo->query('SHOW COLUMNS FROM committee_meetings')->fetchAll(PDO::FETCH_COLUMN);if(!in_array('meeting_mode',$meetingColumns,true))$pdo->exec("ALTER TABLE committee_meetings ADD COLUMN meeting_mode ENUM('In Person','Online','Hybrid') NOT NULL DEFAULT 'In Person' AFTER location,ADD COLUMN quorum_met TINYINT(1) NOT NULL DEFAULT 0 AFTER agenda,ADD COLUMN minutes_approved TINYINT(1) NOT NULL DEFAULT 0 AFTER minutes_summary");
 $recColumns=$pdo->query('SHOW COLUMNS FROM committee_recommendations')->fetchAll(PDO::FETCH_COLUMN);if(!in_array('approval_stage',$recColumns,true))$pdo->exec("ALTER TABLE committee_recommendations ADD COLUMN approval_stage ENUM('Draft','Participant Review','Committee Head Review','Department Head Review','Approved','Rejected') NOT NULL DEFAULT 'Draft' AFTER recommendation_text,ADD COLUMN submitted_by_user_id INT NULL AFTER approval_stage,ADD COLUMN submitted_at DATETIME NULL AFTER submitted_by_user_id,ADD COLUMN approved_at DATETIME NULL AFTER submitted_at,ADD CONSTRAINT fk_recommendation_submitter FOREIGN KEY(submitted_by_user_id) REFERENCES users(id) ON DELETE SET NULL");
 $pdo->exec("CREATE TABLE committee_meeting_agenda_items(id INT AUTO_INCREMENT PRIMARY KEY,meeting_id INT NOT NULL,item_no INT NOT NULL,title VARCHAR(255) NOT NULL,description TEXT NULL,presenter_staff_id INT NULL,allocated_minutes INT UNSIGNED NULL,status ENUM('Planned','Discussed','Deferred','Cancelled') NOT NULL DEFAULT 'Planned',decision_summary TEXT NULL,UNIQUE KEY uq_meeting_agenda_item(meeting_id,item_no),CONSTRAINT fk_agenda_meeting FOREIGN KEY(meeting_id) REFERENCES committee_meetings(id) ON DELETE CASCADE,CONSTRAINT fk_agenda_presenter FOREIGN KEY(presenter_staff_id) REFERENCES program_staff(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("CREATE TABLE committee_recommendation_approvals(id INT AUTO_INCREMENT PRIMARY KEY,recommendation_id INT NOT NULL,staff_id INT NOT NULL,approval_role ENUM('Participant','Committee Head','Department Head') NOT NULL,decision ENUM('Pending','Approved','Rejected','Abstained') NOT NULL DEFAULT 'Pending',comment VARCHAR(1000) NULL,decided_at DATETIME NULL,UNIQUE KEY uq_recommendation_approval(recommendation_id,staff_id,approval_role),KEY idx_recommendation_decision(recommendation_id,decision),CONSTRAINT fk_rec_approval_recommendation FOREIGN KEY(recommendation_id) REFERENCES committee_recommendations(id) ON DELETE CASCADE,CONSTRAINT fk_rec_approval_staff FOREIGN KEY(staff_id) REFERENCES program_staff(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
 $pdo->exec("INSERT INTO committees(committee_name,committee_type,academic_year,mandate,status,notes) SELECT 'Consultancy Committee','Advisory / Consultancy','2025-2027','Provide external and internal consultation, review academic program relevance, advise on stakeholder and labor-market expectations, and issue evidence-based recommendations.','Active','Created by the universal consultancy committee workflow.' WHERE NOT EXISTS(SELECT 1 FROM committees WHERE committee_name='Consultancy Committee')");
};
